using UnityEngine;
using UnityEditor;
using System.IO;

public class CreateVfxPrefabs
{
    public static string Execute()
    {
        Directory.CreateDirectory("Assets/Prefabs/VFX");

        // Standard default particle material
        Material particleMat = AssetDatabase.GetBuiltinExtraResource<Material>("Default-Particle.mat");

        // 1. VFX_MuzzleFlash_Cyber
        {
            GameObject go = new GameObject("VFX_MuzzleFlash_Cyber");
            ParticleSystem ps = go.AddComponent<ParticleSystem>();
            var main = ps.main;
            main.duration = 0.15f;
            main.loop = false;
            main.startLifetime = 0.12f;
            main.startSpeed = new ParticleSystem.MinMaxCurve(8f, 16f);
            main.startSize = new ParticleSystem.MinMaxCurve(0.15f, 0.35f);
            main.startColor = new Color(0f, 0.95f, 1f, 1f); // Cyan
            main.simulationSpace = ParticleSystemSimulationSpace.World;
            main.stopAction = ParticleSystemStopAction.Destroy;

            var emission = ps.emission;
            emission.rateOverTime = 0;
            emission.SetBursts(new ParticleSystem.Burst[] { new ParticleSystem.Burst(0f, 14) });

            var shape = ps.shape;
            shape.shapeType = ParticleSystemShapeType.Cone;
            shape.angle = 18f;
            shape.radius = 0.05f;

            var col = ps.colorOverLifetime;
            col.enabled = true;
            Gradient grad = new Gradient();
            grad.SetKeys(
                new GradientColorKey[] { new GradientColorKey(new Color(0.2f, 1f, 1f), 0f), new GradientColorKey(new Color(0f, 0.6f, 1f), 1f) },
                new GradientAlphaKey[] { new GradientAlphaKey(1f, 0f), new GradientAlphaKey(0f, 1f) }
            );
            col.color = grad;

            var renderer = go.GetComponent<ParticleSystemRenderer>();
            renderer.material = particleMat;
            renderer.sortingLayerName = "Default";
            renderer.sortingOrder = 15;

            PrefabUtility.SaveAsPrefabAsset(go, "Assets/Prefabs/VFX/VFX_MuzzleFlash_Cyber.prefab");
            Object.DestroyImmediate(go);
        }

        // 2. VFX_LaserImpact_Sparks
        {
            GameObject go = new GameObject("VFX_LaserImpact_Sparks");
            ParticleSystem ps = go.AddComponent<ParticleSystem>();
            var main = ps.main;
            main.duration = 0.3f;
            main.loop = false;
            main.startLifetime = new ParticleSystem.MinMaxCurve(0.15f, 0.35f);
            main.startSpeed = new ParticleSystem.MinMaxCurve(5f, 12f);
            main.startSize = new ParticleSystem.MinMaxCurve(0.08f, 0.2f);
            main.startColor = new Color(0f, 0.95f, 1f, 1f);
            main.gravityModifier = 1.2f;
            main.simulationSpace = ParticleSystemSimulationSpace.World;
            main.stopAction = ParticleSystemStopAction.Destroy;

            var emission = ps.emission;
            emission.rateOverTime = 0;
            emission.SetBursts(new ParticleSystem.Burst[] { new ParticleSystem.Burst(0f, 18) });

            var shape = ps.shape;
            shape.shapeType = ParticleSystemShapeType.Sphere;
            shape.radius = 0.1f;

            var col = ps.colorOverLifetime;
            col.enabled = true;
            Gradient grad = new Gradient();
            grad.SetKeys(
                new GradientColorKey[] { new GradientColorKey(Color.white, 0f), new GradientColorKey(new Color(0f, 0.8f, 1f), 1f) },
                new GradientAlphaKey[] { new GradientAlphaKey(1f, 0f), new GradientAlphaKey(0f, 1f) }
            );
            col.color = grad;

            var renderer = go.GetComponent<ParticleSystemRenderer>();
            renderer.material = particleMat;
            renderer.sortingLayerName = "Default";
            renderer.sortingOrder = 15;

            PrefabUtility.SaveAsPrefabAsset(go, "Assets/Prefabs/VFX/VFX_LaserImpact_Sparks.prefab");
            Object.DestroyImmediate(go);
        }

        // 3. VFX_FireballDetonation
        {
            GameObject go = new GameObject("VFX_FireballDetonation");
            ParticleSystem ps = go.AddComponent<ParticleSystem>();
            var main = ps.main;
            main.duration = 0.5f;
            main.loop = false;
            main.startLifetime = new ParticleSystem.MinMaxCurve(0.2f, 0.5f);
            main.startSpeed = new ParticleSystem.MinMaxCurve(6f, 14f);
            main.startSize = new ParticleSystem.MinMaxCurve(0.15f, 0.45f);
            main.startColor = new Color(1f, 0.55f, 0.1f, 1f); // Orange core
            main.gravityModifier = 0.5f;
            main.simulationSpace = ParticleSystemSimulationSpace.World;
            main.stopAction = ParticleSystemStopAction.Destroy;

            var emission = ps.emission;
            emission.rateOverTime = 0;
            emission.SetBursts(new ParticleSystem.Burst[] { new ParticleSystem.Burst(0f, 25) });

            var shape = ps.shape;
            shape.shapeType = ParticleSystemShapeType.Sphere;
            shape.radius = 0.2f;

            var col = ps.colorOverLifetime;
            col.enabled = true;
            Gradient grad = new Gradient();
            grad.SetKeys(
                new GradientColorKey[] { new GradientColorKey(new Color(0f, 1f, 1f), 0f), new GradientColorKey(new Color(1f, 0.4f, 0f), 0.5f), new GradientColorKey(new Color(0.2f, 0.1f, 0.1f), 1f) },
                new GradientAlphaKey[] { new GradientAlphaKey(1f, 0f), new GradientAlphaKey(0.8f, 0.6f), new GradientAlphaKey(0f, 1f) }
            );
            col.color = grad;

            var renderer = go.GetComponent<ParticleSystemRenderer>();
            renderer.material = particleMat;
            renderer.sortingLayerName = "Default";
            renderer.sortingOrder = 16;

            PrefabUtility.SaveAsPrefabAsset(go, "Assets/Prefabs/VFX/VFX_FireballDetonation.prefab");
            Object.DestroyImmediate(go);
        }

        AssetDatabase.Refresh();
        return "VFX Prefabs created successfully!";
    }
}
